import { TestingModule } from '@nestjs/testing';
import { MikroORM } from '@mikro-orm/core';
import { createIntegrationTestModule, cleanDatabase } from './setup';
import { Product } from '../../src/entities/product.entity';
import { buildProduct } from '../factories/product.factory';
import { Category } from '../../src/entities/category.entity';
import { buildCategory } from '../factories/category.factory';

describe('Product Relationships', () => {
  let module: TestingModule;
  let orm: MikroORM;
  let categoryId: string;

  beforeAll(async () => {
    module = await createIntegrationTestModule();
    orm = module.get(MikroORM);
  });

  beforeEach(async () => {
    const em = orm.em.fork();
    const categoryEntity = em.create(
      Category,
      buildCategory(),
    );
    await em.persistAndFlush(categoryEntity);
    categoryId = categoryEntity.id;
  });

  afterEach(async () => {
    await cleanDatabase(orm);
  });

  afterAll(async () => {
    await module.close();
  });

  describe('belongs_to Category', () => {
    it('persists category reference', async () => {
      const em = orm.em.fork();
      const data = buildProduct({ category: categoryId });
      const saved = em.create(Product, data);
      await em.persistAndFlush(saved);
      await em.populate(saved, ['category']);
      expect(saved.category.id).toBe(categoryId);
    });

    it('loads parent via relation', async () => {
      const em = orm.em.fork();
      const data = buildProduct({ category: categoryId });
      const saved = em.create(Product, data);
      await em.persistAndFlush(saved);
      const loaded = await em.findOne(
        Product,
        { id: saved.id },
        { populate: ['category'] },
      );
      expect(loaded).not.toBeNull();
      expect(loaded!.category).toBeDefined();
      expect(loaded!.category.id).toBe(categoryId);
    });

    it('rejects entity without required category', async () => {
      const em = orm.em.fork();
      const data = buildProduct({ category: undefined as unknown as string });
      const row = em.create(Product, data);
      await expect(em.persistAndFlush(row)).rejects.toThrow();
    });
  });
});
